25	static urma_device_t *ascend_urma_get_device_when_hd_ub_conn(u32 devid, u32 *eid_index)
26	{
27	    struct dms_ub_dev_info eid_info = {{0}};
28	    int num, ret;
29	
30	    ret = dms_get_ub_dev_info(devid, &eid_info, &num);
31	    if ((ret != DRV_ERROR_NONE) || (num == 0)) {
32	        ascend_urma_info("dms_get_ub_dev_info check. (ret=%d)\n", ret);
33	        return NULL;
34	    }
35	
36	    *eid_index = eid_info.eid_index[0];
37	    return (urma_device_t *)eid_info.urma_dev[0];
38	}
39	
40	static urma_device_t *ascend_urma_get_device_when_hd_others_conn(u32 devid, u32 *eid_index)
41	{
42	    urma_eid_info_t *eid_info = NULL;
43	    urma_device_t **urma_dev_list = NULL;
44	    urma_device_t *urma_dev = NULL;
45	    int i, num_devices;
46	    uint32_t cnt;
47	
48	    urma_dev_list = urma_get_device_list(&num_devices);
49	    if (urma_dev_list == NULL) {
50	        ascend_urma_info("Get null urma_device_list notice.\n");
51	        return NULL;
52	    }
53	
54	    for (i = 0; i < num_devices; i++) {
55	        eid_info = urma_get_eid_list(urma_dev_list[i], &cnt);
56	        if ((eid_info != NULL) && (cnt != 0)) {
57	            *eid_index = eid_info[0].eid_index;
58	            urma_dev = urma_dev_list[i];
59	            urma_free_eid_list(eid_info);
60	            break;
61	        }
62	        urma_free_eid_list(eid_info);
63	    }
64	    urma_free_device_list(urma_dev_list);
65	
66	    return urma_dev;
67	}
