69	urma_device_t *ascend_urma_get_device(u32 devid, u32 *eid_index)
70	{
71	    int64_t hd_connect_type;
72	    int ret;
73	
74	    ret = halGetDeviceInfo(devid, MODULE_TYPE_SYSTEM, INFO_TYPE_HD_CONNECT_TYPE, &hd_connect_type);
75	    if (ret != DRV_ERROR_NONE) {
76	        ascend_urma_info("halGetDeviceInfo check. (devid=%u; ret=%d)\n", devid, ret);
77	        return NULL;
78	    }
79	
80	    if (hd_connect_type == HOST_DEVICE_CONNECT_TYPE_UB) {
81	        return ascend_urma_get_device_when_hd_ub_conn(devid, eid_index);
82	    } else {
83	        return ascend_urma_get_device_when_hd_others_conn(devid, eid_index);
84	    }
85	}
