87	int ascend_urma_get_urma_dev_name(uint32_t devid, char *name, uint32_t *size)
88	{
89	    urma_device_t *urma_dev = NULL;
90	    u32 urma_dev_name_size = 0;
91	    u32 eid_index = UINT32_MAX;
92	    int ret;
93	
94	    urma_dev = ascend_urma_get_device(devid, &eid_index);
95	    if (urma_dev == NULL) {
96	        ascend_urma_err("ascend_urma_get_device get device failed, urma_dev is NULL. (devid=%u)\n", devid);
97	        return DRV_ERROR_INVALID_VALUE;
98	    }
99	
100	    urma_dev_name_size = (u32)strnlen(urma_dev->name, URMA_MAX_NAME);
101	    if ((name == NULL) || (size == NULL) || (*size < urma_dev_name_size + 1)) {
102	        ascend_urma_err("Input params is invalid. (devid=%u; name_is_null=%d; size_is_null=%d; size=%u; name_len=%u)\n",
103	                        devid, name == NULL, size == NULL, size == NULL ? 0 : *size, urma_dev_name_size);
104	        return DRV_ERROR_INVALID_VALUE;
105	    }
106	
107	    ret = strncpy_s(name, *size, urma_dev->name, urma_dev_name_size);
108	    if (ret != 0) {
109	        ascend_urma_err("strncpy_s failed. (devid=%u; ret=%d)\n", devid, ret);
110	        return ret;
111	    }
112	
113	    *size = urma_dev_name_size;
114	
115	    return DRV_ERROR_NONE;
116	}
