48	static inline bool ascend_urma_token_flag_bit_is_set(u32 flag, u32 bit_mask)
49	{
50	    return ((flag & bit_mask) != 0);
51	}
52	
53	static inline bool ascend_urma_token_flag_is_unique(u32 flag)
54	{
55	    return ascend_urma_token_flag_bit_is_set(flag, ASCEND_URMA_TOKEN_FLAG_UNIQUE);
56	}
57	
58	static void ascend_urma_token_acquired_num_inc(struct ascend_urma_token *token)
59	{
60	    token->acquired_num++;
61	}
62	
63	static void ascend_urma_token_acquired_num_dec(struct ascend_urma_token *token)
64	{
65	    token->acquired_num--;
66	}
67	
68	static struct ascend_urma_token *ascend_urma_token_alloc(void *urma_ctx, struct ascend_urma_token_pool *pool)
69	{
70	    struct ascend_urma_token *token = NULL;
71	
72	    token = calloc(1, sizeof(struct ascend_urma_token));
73	    if (token == NULL) {
74	        ascend_urma_err("Malloc failed. (size=%llu)\n", (u64)sizeof(struct ascend_urma_token));
75	        return NULL;
76	    }
77	
78	    INIT_LIST_HEAD(&token->node);
79	    token->pool = (void *)pool;
80	    token->acquired_num = 0;
81	    token->token_val.token = pool->token_val;
82	    token->token_id = urma_alloc_token_id(ascend_to_urma_ctx(urma_ctx));
83	    if (token->token_id == NULL) {
84	        ascend_urma_err("Urma alloc token id failed.\n");
85	        free(token);
86	        return NULL;
87	    }
88	
89	    return token;
90	}
91	
92	static void ascend_urma_token_free(struct ascend_urma_token *token)
93	{
94	    (void)urma_free_token_id(token->token_id);
95	    free(token);
96	}
97	
98	static struct ascend_urma_token *_ascend_urma_get_first_token(struct ascend_urma_token_pool *pool)
99	{
100	    return ((drv_user_list_empty(&pool->head) == 1) ? NULL :
101	                                                      container_of(pool->head.next, struct ascend_urma_token, node));
102	}
103	
104	static void _ascend_urma_token_insert(struct ascend_urma_token_pool *pool, struct ascend_urma_token *token)
105	{
106	    drv_user_list_add_head(&token->node, &pool->head);
107	    pool->total_num++;
108	    pool->cur_token = token;
109	}
110	
111	static void _ascend_urma_token_erase(struct ascend_urma_token_pool *pool, struct ascend_urma_token *token)
112	{
113	    drv_user_list_del(&token->node);
114	    pool->total_num--;
115	    if (pool->cur_token == token) {
116	        pool->cur_token = _ascend_urma_get_first_token(pool);
117	    }
118	}
119	
120	static struct ascend_urma_token_pool *ascend_urma_token_pool_alloc(u32 devid, struct ascend_urma_token_pool_attr *attr)
121	{
122	    struct ascend_urma_token_pool *pool = NULL;
123	
124	    pool = calloc(1, sizeof(struct ascend_urma_token_pool));
125	    if (pool == NULL) {
126	        ascend_urma_err("Malloc failed. (size=%llu)\n", (u64)sizeof(struct ascend_urma_token_pool));
127	        return NULL;
128	    }
129	
130	    (void)pthread_rwlock_init(&pool->rwlock, NULL);
131	    INIT_LIST_HEAD(&pool->head);
132	    pool->attr = *attr;
133	    pool->devid = devid;
134	    pool->total_num = 0;
135	    pool->cur_token = NULL;
136	
137	    return pool;
138	}
139	
140	static void ascend_urma_token_pool_free(struct ascend_urma_token_pool *pool)
141	{
142	    free(pool);
143	}
144	
145	static void ascend_urma_token_pool_uninit(struct ascend_urma_token_pool *pool)
146	{
147	    struct ascend_urma_token *token = NULL;
148	    struct list_head *pos = NULL, *n = NULL;
149	
150	    list_for_each_safe(pos, n, &pool->head)
151	    {
152	        token = container_of(pos, struct ascend_urma_token, node);
153	        _ascend_urma_token_erase(pool, token);
154	        ascend_urma_token_free(token);
155	    }
156	}
157	
158	static int _ascend_urma_token_pool_init(void *urma_ctx, struct ascend_urma_token_pool *pool)
159	{
160	    struct ascend_urma_token *token = NULL;
161	    u32 token_val, i = 0;
162	    int ret;
163	
164	    ret = ascend_urma_get_token_val(pool->devid, &token_val);
165	    if (ret != DRV_ERROR_NONE) {
166	        return ret;
167	    }
168	    pool->token_val = token_val;
169	
170	    for (i = 0; i < pool->attr.token_num_default; i++) {
171	        token = ascend_urma_token_alloc(urma_ctx, pool);
172	        if (token == NULL) {
173	            ascend_urma_token_pool_uninit(pool);
174	            return DRV_ERROR_INNER_ERR;
175	        }
176	
177	        _ascend_urma_token_insert(pool, token);
178	    }
179	
180	    return DRV_ERROR_NONE;
181	}
182	
183	static int ascend_urma_token_pool_init(struct ascend_urma_token_pool *pool)
184	{
185	    void *urma_ctx = NULL;
186	    int ret;
187	
188	    urma_ctx = ascend_urma_ctx_get(pool->devid);
189	    if (urma_ctx == NULL) {
190	        ascend_urma_err("Get ascend_urma_ctx failed. (devid=%u)\n", pool->devid);
191	        return DRV_ERROR_UNINIT;
192	    }
193	
194	    ret = _ascend_urma_token_pool_init(urma_ctx, pool);
195	    ascend_urma_ctx_put(urma_ctx);
196	    return ret;
197	}
198	
199	struct ascend_urma_token *ascend_urma_token_acquir_new(struct ascend_urma_token_pool *pool)
200	{
201	    void *urma_ctx = NULL;
202	    struct ascend_urma_token *token = NULL;
203	    u32 devid = pool->devid;
204	
205	    urma_ctx = ascend_urma_ctx_get(devid);
206	    if (urma_ctx == NULL) {
207	        ascend_urma_err("Get ascend_urma_ctx failed. (devid=%u)\n", devid);
208	        return NULL;
209	    }
210	
211	    token = ascend_urma_token_alloc(urma_ctx, pool);
212	    ascend_urma_ctx_put(urma_ctx);
213	    if (token != NULL) {
214	        ascend_urma_token_acquired_num_inc(token);
215	        _ascend_urma_token_insert(pool, token);
216	    }
217	
218	    return token;
219	}
220	
221	static struct ascend_urma_token *ascend_urma_token_acquire_old(struct ascend_urma_token_pool *pool)
222	{
223	    struct ascend_urma_token *token = NULL;
224	    struct list_head *pos = NULL, *n = NULL;
225	
226	    if ((pool->cur_token != NULL) && (pool->cur_token->acquired_num < pool->attr.max_acquired_num_per_token)) {
227	        ascend_urma_token_acquired_num_inc(pool->cur_token);
228	        return pool->cur_token;
229	    }
230	
231	    list_for_each_safe(pos, n, &pool->head)
232	    {
233	        token = container_of(pos, struct ascend_urma_token, node);
234	        if (token->acquired_num < pool->attr.max_acquired_num_per_token) {
235	            ascend_urma_token_acquired_num_inc(token);
236	            pool->cur_token = token;
237	            return token;
238	        }
239	    }
240	
241	    return NULL;
242	}
243	
244	static struct ascend_urma_token *_ascend_urma_token_acquire(struct ascend_urma_token_pool *pool, u32 token_flag)
245	{
246	    struct ascend_urma_token *token = NULL;
247	
248	    if (!ascend_urma_token_flag_is_unique(token_flag)) {
249	        token = ascend_urma_token_acquire_old(pool);
250	        if (token != NULL) {
251	            return token;
252	        }
253	    }
254	
255	    return ascend_urma_token_acquir_new(pool);
256	}
257	
258	static bool ascend_urma_token_pool_is_to_cache_up_thres(struct ascend_urma_token_pool *pool)
259	{
260	    return (pool->total_num >= pool->attr.token_num_cache_up_thres);
261	}
262	
263	static void _ascend_urma_token_release(struct ascend_urma_token_pool *pool, struct ascend_urma_token *token)
264	{
265	    ascend_urma_token_acquired_num_dec(token);
266	    if ((token->acquired_num == 0) && ascend_urma_token_pool_is_to_cache_up_thres(pool)) {
267	        _ascend_urma_token_erase(pool, token);
268	        ascend_urma_token_free(token);
269	    }
270	}
271	
272	void *ascend_urma_token_pool_create(u32 devid, struct ascend_urma_token_pool_attr *attr)
273	{
274	    struct ascend_urma_token_pool *pool = NULL;
275	    int ret;
276	
277	    pool = ascend_urma_token_pool_alloc(devid, attr);
278	    if (pool == NULL) {
279	        return NULL;
280	    }
281	
282	    ret = ascend_urma_token_pool_init(pool);
283	    if (ret != DRV_ERROR_NONE) {
284	        ascend_urma_token_pool_free(pool);
285	        return NULL;
286	    }
287	
288	    return (void *)pool;
