114	static int update_timecost(struct timespec *start_time, int time_out, int *real_time_out)
115	{
116	    struct timespec current_time;
117	    long recv_time, wait_time;
118	
119	    if (time_out < 0) {
120	        *real_time_out = time_out;
121	        return DRV_ERROR_NONE;
122	    }
123	
124	    wait_time = time_out;
125	    (void)clock_gettime(CLOCK_MONOTONIC, &current_time);
126	
127	    recv_time = (current_time.tv_sec * MS_PER_SECOND + current_time.tv_nsec / NS_PER_MSECOND) -
128	                (start_time->tv_sec * MS_PER_SECOND + start_time->tv_nsec / NS_PER_MSECOND);
129	    if (recv_time >= wait_time) {
130	        return DRV_ERROR_INNER_ERR;
131	    }
132	
133	    *real_time_out = time_out - (int)recv_time;
134	    return DRV_ERROR_NONE;
135	}
