28	struct ascend_urma_seg_mng {
29	    pthread_rwlock_t rwlock;
30	    struct rbtree_root rb_root;
31	
32	    u32 devid;
33	    void *token_pool;
34	    struct ascend_urma_seg_mng_attr attr;
35	};
36	
37	struct ascend_urma_seg {
38	    struct rbtree_node node;
39	    atomic_int ref;
40	
41	    u64 start;
42	    u64 size;
43	    u32 seg_flag;
44	    void *token;
45	
46	    urma_target_seg_t *tseg;
47	};
48	
49	static inline bool ascend_urma_seg_flag_bit_is_set(u32 flag, u32 bit_mask)
50	{
51	    return ((flag & bit_mask) != 0);
52	}
53	
54	static inline bool ascend_urma_seg_flag_is_access_write(u32 flag)
55	{
56	    return ascend_urma_seg_flag_bit_is_set(flag, ASCEND_URMA_SEG_FLAG_ACCESS_WRITE);
57	}
58	
59	static inline bool ascend_urma_seg_flag_is_pin(u32 flag)
60	{
61	    return ascend_urma_seg_flag_bit_is_set(flag, ASCEND_URMA_SEG_FLAG_PIN);
62	}
63	
64	static inline bool ascend_urma_seg_flag_is_without_token_val(u32 flag)
65	{
66	    return ascend_urma_seg_flag_bit_is_set(flag, ASCEND_URMA_SEG_FLAG_WITHOUT_TOKEN_VAL);
67	}
68	
69	static void rb_range_handle_of_ascend_urma_seg(struct rbtree_node *node, struct rb_range_handle *range_handle)
70	{
71	    struct ascend_urma_seg *seg = rb_entry(node, struct ascend_urma_seg, node);
72	
73	    range_handle->start = seg->start;
74	    range_handle->end = seg->start + seg->size - 1;
75	}
76	
77	static urma_target_seg_t *_ascend_urma_register_segment(void *urma_ctx, u64 start, u64 size, u32 seg_flag, void *token)
78	{
79	    urma_target_seg_t *tseg = NULL;
80	    urma_seg_cfg_t seg_cfg = {0};
81	
82	    seg_cfg.va = ascend_urma_adapt_align_down(start, (u64)getpagesize());
83	    seg_cfg.len = ascend_urma_adapt_align_up(start + size, (u64)getpagesize()) - seg_cfg.va;
84	    seg_cfg.token_id = ascend_urma_token_to_id(token);
85	    seg_cfg.token_value = ascend_urma_token_to_val(token);
86	
87	    seg_cfg.flag.bs.token_policy = ascend_urma_seg_flag_is_without_token_val(seg_flag) ? URMA_TOKEN_NONE :
88	                                                                                         URMA_TOKEN_PLAIN_TEXT;
89	    seg_cfg.flag.bs.cacheable = URMA_CACHEABLE;
90	    seg_cfg.flag.bs.dsva = 0;
91	
92	    if (ascend_urma_seg_flag_is_access_write(seg_flag)) {
93	        seg_cfg.flag.bs.access = URMA_ACCESS_READ | URMA_ACCESS_WRITE | URMA_ACCESS_ATOMIC;
94	    } else {
95	        seg_cfg.flag.bs.access = URMA_ACCESS_READ;
96	    }
97	
98	    seg_cfg.flag.bs.non_pin = ascend_urma_seg_flag_is_pin(seg_flag) ? 0 : 1;
99	    seg_cfg.flag.bs.user_iova = 0;
100	    seg_cfg.flag.bs.token_id_valid = 1;
101	    seg_cfg.flag.bs.reserved = 0;
102	
103	    tseg = urma_register_seg(ascend_to_urma_ctx(urma_ctx), &seg_cfg);
104	    if (tseg == NULL) {
105	        ascend_urma_err("Urma register seg failed.\n");
106	    }
107	
108	    return tseg;
109	}
110	
111	static urma_target_seg_t *ascend_urma_register_segment(u32 devid, u64 start, u64 size, u32 seg_flag, void *token)
112	{
113	    void *urma_ctx = NULL;
114	    urma_target_seg_t *tseg = NULL;
115	
116	    urma_ctx = ascend_urma_ctx_get(devid);
117	    if (urma_ctx == NULL) {
118	        ascend_urma_err("Get ascend_urma_ctx failed. (devid=%u)\n", devid);
119	        return NULL;
120	    }
121	
122	    tseg = _ascend_urma_register_segment(urma_ctx, start, size, seg_flag, token);
123	    ascend_urma_ctx_put(urma_ctx);
124	    return tseg;
125	}
126	
127	static void ascend_urma_unregister_segment(urma_target_seg_t *tseg)
128	{
129	    (void)urma_unregister_seg(tseg);
130	}
131	
132	static struct ascend_urma_seg *ascend_urma_seg_alloc(u32 devid, u64 start, u64 size, u32 seg_flag, void *token)
133	{
134	    struct ascend_urma_seg *seg = NULL;
135	    urma_target_seg_t *tseg = NULL;
136	
137	    seg = calloc(1, sizeof(struct ascend_urma_seg));
138	    if (seg == NULL) {
139	        ascend_urma_err("Calloc ascend_urma_seg_inst failed. (size=%zu)\n", sizeof(struct ascend_urma_seg));
140	        return NULL;
141	    }
142	
143	    tseg = ascend_urma_register_segment(devid, start, size, seg_flag, token);
144	    if (tseg == NULL) {
145	        free(seg);
146	        return NULL;
147	    }
148	
149	    RB_CLEAR_NODE(&seg->node);
150	    seg->start = start;
151	    seg->size = size;
152	    seg->seg_flag = seg_flag;
153	    seg->token = token;
154	    seg->tseg = tseg;
155	    atomic_init(&seg->ref, 0);
156	
157	    return seg;
158	}
159	
160	static void ascend_urma_seg_free(struct ascend_urma_seg *seg)
161	{
162	    ascend_urma_unregister_segment(seg->tseg);
163	    free(seg);
164	}
165	
166	static void ascend_urma_seg_erase(struct ascend_urma_seg_mng *seg_mng, struct ascend_urma_seg *seg)
167	{
168	    _rbtree_erase(&seg_mng->rb_root, &seg->node);
169	}
170	
171	static int ascend_urma_seg_insert(struct ascend_urma_seg_mng *seg_mng, struct ascend_urma_seg *seg)
172	{
173	    int ret;
174	
175	    ret = rbtree_insert_by_range(&seg_mng->rb_root, &seg->node, rb_range_handle_of_ascend_urma_seg);
176	    return (ret != 0) ? DRV_ERROR_BUSY : DRV_ERROR_NONE;
177	}
178	
179	static struct ascend_urma_seg *ascend_urma_get_seg(struct ascend_urma_seg_mng *seg_mng, u64 start, u64 size)
180	{
181	    struct rbtree_node *rb_node = NULL;
182	    struct rb_range_handle range = {.start = start, .end = start + size - 1};
183	
184	    rb_node = rbtree_search_by_range(&seg_mng->rb_root, &range, rb_range_handle_of_ascend_urma_seg);
185	    if (rb_node == NULL) {
186	        return NULL;
187	    }
188	
189	    return rb_entry(rb_node, struct ascend_urma_seg, node);
190	}
191	
192	static bool ascend_urma_exist_registered_seg_in_range(struct ascend_urma_seg_mng *seg_mng, u64 start, u64 size)
193	{
194	    struct rb_range_handle range_handle = {.start = start, .end = start + size - 1};
195	
196	    return (rbtree_can_insert_range(&seg_mng->rb_root, &range_handle, rb_range_handle_of_ascend_urma_seg) == false);
197	}
198	
199	static int ascend_urma_seg_register(struct ascend_urma_seg_mng *seg_mng, u64 start, u64 size, u32 seg_flag)
200	{
201	    struct ascend_urma_seg *seg = NULL, *tmp_seg = NULL;
202	    void *token = NULL;
203	    u64 aligned_va = ascend_urma_adapt_align_down(start, (u64)getpagesize());
204	    u64 aligned_size = ascend_urma_adapt_align_up(start + size, (u64)getpagesize()) - aligned_va;
205	    u32 devid = seg_mng->devid;
206	    u32 token_flag = 0;
207	    int ret;
208	
209	    tmp_seg = ascend_urma_get_seg(seg_mng, start, size);
210	    if (tmp_seg != NULL) {
211	        if ((tmp_seg->start != start) || (tmp_seg->size != size)) {
212	            ascend_urma_debug("Urma seg info is overlap. (start=0x%llx; size=%llu; seg_start=0x%llx; seg_size=%llu)\n",
213	                              start, size, tmp_seg->start, tmp_seg->size);
214	            return DRV_ERROR_BUSY;
215	        }
216	        atomic_fetch_add(&tmp_seg->ref, 1);
217	        return 0;
218	    }
219	
220	    token_flag |= ascend_urma_exist_registered_seg_in_range(seg_mng, aligned_va, aligned_size) ?
221	                      ASCEND_URMA_TOKEN_FLAG_UNIQUE :
222	                      0;
223	
224	    token = ascend_urma_token_acquire(seg_mng->token_pool, token_flag);
225	    if (token == NULL) {
226	        ascend_urma_err("Acquire token failed. (token_flag=0x%x)\n", token_flag);
227	        return DRV_ERROR_INNER_ERR;
228	    }
229	
230	    seg = ascend_urma_seg_alloc(devid, start, size, seg_flag, token);
231	    if (seg == NULL) {
232	        ascend_urma_err("Alloc seg failed. (devid=%u; start=0x%llx; size=%llu; flag=0x%x)\n", devid, start, size,
233	                        seg_flag);
234	        ascend_urma_token_release(token);
235	        return DRV_ERROR_PARA_ERROR;
236	    }
237	
238	    ret = ascend_urma_seg_insert(seg_mng, seg);
239	    if (ret != DRV_ERROR_NONE) {
240	        ascend_urma_debug("Insert seg check. (devid=%u; start=0x%llx; size=%llu; flag=0x%x)\n", devid, start, size,
241	                          seg_flag);
242	        ascend_urma_seg_free(seg);
243	        ascend_urma_token_release(token);
244	        return ret;
245	    }
246	
247	    atomic_fetch_add(&seg->ref, 1);
248	    return DRV_ERROR_NONE;
249	}
250	
251	static void _ascend_urma_seg_unregister(struct ascend_urma_seg_mng *seg_mng, struct ascend_urma_seg *seg)
252	{
253	    void *token = seg->token;
254	
255	    ascend_urma_seg_erase(seg_mng, seg);
256	    ascend_urma_seg_free(seg);
257	    ascend_urma_token_release(token);
258	}
259	
260	static int ascend_urma_seg_unregister(struct ascend_urma_seg_mng *seg_mng, u64 start, u64 size)
261	{
262	    struct ascend_urma_seg *seg = NULL;
263	
264	    seg = ascend_urma_get_seg(seg_mng, start, size);
265	    if (seg == NULL) {
266	        ascend_urma_err("Get seg failed. (start=0x%llx; size=%llu)\n", start, size);
267	        return DRV_ERROR_INVALID_VALUE;
268	    }
269	    if ((start != seg->start) || (size != seg->size)) {
270	        ascend_urma_err("Addr not match. (start=0x%llx; size=0x%llx; seg.start=0x%llx; seg.size=0x%llx)\n", start, size,
271	                        seg->start, seg->size);
272	        return DRV_ERROR_INVALID_VALUE;
273	    }
274	
275	    if (atomic_load(&seg->ref) > 1) {
276	        atomic_fetch_sub(&seg->ref, 1);
277	        return DRV_ERROR_NONE;
278	    }
279	    _ascend_urma_seg_unregister(seg_mng, seg);
280	    return DRV_ERROR_NONE;
281	}
282	
283	int ascend_urma_seg_get_info(struct ascend_urma_seg_mng *seg_mng, u64 va, struct ascend_urma_seg_info *info)
284	{
285	    struct ascend_urma_seg *seg = NULL;
286	    urma_token_id_t *urma_token_id = NULL;
287	    urma_token_t urma_token_val;
288	
289	    seg = ascend_urma_get_seg(seg_mng, va, 1ULL);
290	    if (seg == NULL) {
291	        return DRV_ERROR_INVALID_VALUE;
292	    }
293	
294	    urma_token_id = ascend_urma_token_to_id(seg->token);
295	    urma_token_val = ascend_urma_token_to_val(seg->token);
296	
297	    info->start = seg->start;
298	    info->size = seg->size;
299	    info->token_id = urma_token_id->token_id;
300	    info->token_val = urma_token_val.token;
301	    info->seg_flag = seg->seg_flag;
302	    info->tseg = seg->tseg;
303	
304	    return DRV_ERROR_NONE;
305	}
306	
307	static void ascend_urma_seg_mng_init(struct ascend_urma_seg_mng *seg_mng, u32 devid)
308	{
309	    (void)pthread_rwlock_init(&seg_mng->rwlock, NULL);
310	    rbtree_init(&seg_mng->rb_root);
311	    seg_mng->devid = devid;
312	}
313	
314	static void ascend_urma_seg_mng_uninit(struct ascend_urma_seg_mng *seg_mng)
315	{
316	    struct ascend_urma_seg *seg = NULL;
317	    struct rbtree_node *cur = NULL;
318	    struct rbtree_node *n = NULL;
319	
320	    (void)pthread_rwlock_wrlock(&seg_mng->rwlock);
321	    rbtree_node_for_each_prev_safe(cur, n, &seg_mng->rb_root)
322	    {
323	        seg = rb_entry(cur, struct ascend_urma_seg, node);
324	        _ascend_urma_seg_unregister(seg_mng, seg);
325	    }
326	    (void)pthread_rwlock_unlock(&seg_mng->rwlock);
327	}
328	
329	static struct ascend_urma_seg_mng *_ascend_urma_seg_mng_create(u32 devid, void *token_pool,
330	                                                               struct ascend_urma_seg_mng_attr *attr)
331	{
332	    struct ascend_urma_seg_mng *seg_mng = NULL;
333	
334	    seg_mng = calloc(1, sizeof(struct ascend_urma_seg_mng));
335	    if (seg_mng == NULL) {
336	        ascend_urma_err("Malloc failed. (size=%llu)\n", (u64)sizeof(struct ascend_urma_seg_mng));
337	        return NULL;
338	    }
339	
340	    seg_mng->attr = *attr;
341	    seg_mng->token_pool = token_pool;
342	    ascend_urma_seg_mng_init(seg_mng, devid);
343	    return seg_mng;
344	}
345	
346	static void _ascend_urma_seg_mng_destroy(struct ascend_urma_seg_mng *seg_mng)
347	{
348	    ascend_urma_seg_mng_uninit(seg_mng);
349	    free(seg_mng);
350	}
351	
352	static void ascend_urma_seg_mng_to_token_pool_attr(struct ascend_urma_seg_mng_attr *seg_mng_attr,
353	                                                   struct ascend_urma_token_pool_attr *token_pool_attr)
354	{
355	    token_pool_attr->token_num_default = seg_mng_attr->token_num_default;
356	    token_pool_attr->token_num_cache_up_thres = seg_mng_attr->token_num_cache_up_thres;
357	    token_pool_attr->max_acquired_num_per_token = seg_mng_attr->max_seg_num_per_token;
358	}
359	
360	void *ascend_urma_seg_mng_create(uint32_t devid, struct ascend_urma_seg_mng_attr *attr)
361	{
362	    struct ascend_urma_token_pool_attr token_pool_attr;
363	    struct ascend_urma_seg_mng *seg_mng = NULL;
364	    void *token_pool;
365	
366	    ascend_urma_seg_mng_to_token_pool_attr(attr, &token_pool_attr);
367	    token_pool = ascend_urma_token_pool_create(devid, &token_pool_attr);
368	    if (token_pool == NULL) {
369	        ascend_urma_err("Create token pool failed. (devid=%u)\n", devid);
370	        return NULL;
371	    }
372	
373	    seg_mng = _ascend_urma_seg_mng_create(devid, token_pool, attr);
374	    if (seg_mng == NULL) {
375	        ascend_urma_token_pool_destroy(token_pool);
376	        return NULL;
377	    }
378	
379	    return seg_mng;
380	}
381	
382	void ascend_urma_seg_mng_destroy(void *seg_mng)
383	{
384	    struct ascend_urma_seg_mng *ascend_seg_mng = (struct ascend_urma_seg_mng *)seg_mng;
385	    void *token_pool = ascend_seg_mng->token_pool;
386	
387	    _ascend_urma_seg_mng_destroy(ascend_seg_mng);
