10	#include "ascend_hal.h"
11	
12	#include "comm_user_interface.h"
13	
14	#include "svm_pub.h"
15	#include "svm_criu.h"
16	#include "svm_log.h"
17	#include "svm_init_pri.h"
18	#include "svm_dbi.h"
19	#include "svm_sys_cmd.h"
20	#include "svm_urma_to_ascend_flag.h"
