22	
23	#ifdef DRV_HOST
24	#define SVM_URMA_TOKEN_DEFAULT_NUM 64u
25	#else
26	#define SVM_URMA_TOKEN_DEFAULT_NUM 2u
27	#endif
28	#define SVM_URMA_TOKEN_CACHE_UP_THRES_NUM 128u
29	#define SVM_URMA_MAX_ACQUIRED_NUM_PER_TOKEN 512u
30	
31	static void *g_seg_mng[SVM_MAX_DEV_AGENT_NUM] = {NULL};
32	static void *g_self_user_seg_mng[SVM_MAX_DEV_AGENT_NUM] = {NULL};
33	static bool g_is_host_side_called = false;
34	static bool g_is_host_side = false;
35	static u32 g_host_user_devid = SVM_MAX_DEV_AGENT_NUM;
36	static bool g_host_user_devid_called = false;
37	
38	static void svm_urma_seg_local_reset_state(void)
39	{
40	    g_is_host_side_called = false;
41	    g_is_host_side = false;
42	    g_host_user_devid = SVM_MAX_DEV_AGENT_NUM;
43	    g_host_user_devid_called = false;
44	}
45	
46	static bool svm_is_in_host_side(void)
47	{
48	    u32 side = 0;
49	
50	    if (!g_is_host_side_called) {
51	        int ret = drvGetPlatformInfo(&side);
52	        if (ret != 0) {
53	            svm_warn("Get side info failed. (ret=%d)\n", ret);
54	        }
55	        g_is_host_side = (side != 0);
56	        g_is_host_side_called = true;
57	    }
58	
59	    return g_is_host_side;
60	}
61	
62	static u32 svm_urma_seg_get_user_devid(u32 devid)
63	{
64	    u32 dev_num, i;
65	
66	    if (svm_is_in_host_side() == false) {
67	        return devid;
68	    }
69	
70	    (void)drvGetDevNum(&dev_num);
71	    if (!g_host_user_devid_called) {
72	        for (i = 0; i < dev_num; ++i) {
73	            if (ascend_urma_dev_is_exist(i)) {
74	                g_host_user_devid = i;
75	                break;
76	            }
77	        }
78	    }
79	    g_host_user_devid_called = true;
80	    return g_host_user_devid;
81	}
82	
83	static void *svm_get_urma_seg_mng(u32 devid, u32 seg_flag)
84	{
85	    if (svm_urma_seg_flag_is_self_user(seg_flag)) {
86	        return g_self_user_seg_mng[devid];
87	    } else {
88	        return g_seg_mng[devid];
89	    }
90	}
91	
92	static bool svm_urma_seg_local_is_dev_inited(u32 devid)
93	{
94	    return ((g_seg_mng[devid] != NULL) && (g_self_user_seg_mng[devid]));
95	}
96	
97	static int _svm_urma_seg_local_dev_init(u32 devid)
98	{
99	    struct ascend_urma_seg_mng_attr attr = {.token_num_default = SVM_URMA_TOKEN_DEFAULT_NUM,
100	                                            .token_num_cache_up_thres = SVM_URMA_TOKEN_CACHE_UP_THRES_NUM,
101	                                            .max_seg_num_per_token = SVM_URMA_MAX_ACQUIRED_NUM_PER_TOKEN};
102	    void *seg_mng = NULL;
103	    void *slef_user_seg_mng = NULL;
104	
105	    seg_mng = ascend_urma_seg_mng_create(devid, &attr);
106	    if (seg_mng == NULL) {
107	        svm_err("Create urma seg mng failed. (devid=%d)\n", devid);
108	        return DRV_ERROR_INNER_ERR;
109	    }
110	
111	    slef_user_seg_mng = ascend_urma_seg_mng_create(devid, &attr);
112	    if (slef_user_seg_mng == NULL) {
113	        svm_err("Create urma seg mng failed. (devid=%d)\n", devid);
114	        ascend_urma_seg_mng_destroy(seg_mng);
115	        return DRV_ERROR_INNER_ERR;
116	    }
117	
118	    g_seg_mng[devid] = seg_mng;
119	    g_self_user_seg_mng[devid] = slef_user_seg_mng;
120	    return DRV_ERROR_NONE;
121	}
122	
123	static void _svm_urma_seg_local_dev_uninit(u32 devid)
124	{
125	    ascend_urma_seg_mng_destroy(g_self_user_seg_mng[devid]);
126	    ascend_urma_seg_mng_destroy(g_seg_mng[devid]);
127	    g_self_user_seg_mng[devid] = NULL;
128	    g_seg_mng[devid] = NULL;
129	}
130	
131	int svm_urma_seg_local_register(u32 devid, u64 start, u64 size, u32 seg_flag)
132	{
133	    u32 user_devid = svm_urma_seg_get_user_devid(devid);
134	
135	    if (user_devid >= SVM_MAX_DEV_AGENT_NUM) {
136	        svm_err("Invalid devid. (devid=%u)\n", user_devid);
137	        return DRV_ERROR_INVALID_VALUE;
138	    }
139	
140	    if (!svm_urma_seg_local_is_dev_inited(user_devid)) {
141	        svm_err("Uninit. (devid=%u)\n", user_devid);
142	        return DRV_ERROR_INVALID_VALUE;
143	    }
144	
145	    return ascend_urma_register_seg(svm_get_urma_seg_mng(user_devid, seg_flag), start, size,
146	                                    svm_urma_to_ascend_seg_flag(seg_flag));
147	}
148	
149	int svm_urma_seg_local_unregister(u32 devid, u64 start, u64 size, u32 seg_flag)
150	{
151	    u32 user_devid = svm_urma_seg_get_user_devid(devid);
152	
153	    if (user_devid >= SVM_MAX_DEV_AGENT_NUM) {
154	        svm_err("Invalid devid. (devid=%u)\n", user_devid);
155	        return DRV_ERROR_INVALID_VALUE;
156	    }
157	
158	    if (!svm_urma_seg_local_is_dev_inited(user_devid)) {
159	        svm_err("Uninit. (devid=%u)\n", user_devid);
160	        return DRV_ERROR_INVALID_VALUE;
161	    }
162	
163	    return ascend_urma_unregister_seg(svm_get_urma_seg_mng(user_devid, seg_flag), start, size);
164	}
165	
166	static inline u32 ascend_to_svm_urma_seg_flag(u32 ascend_flag)
167	{
168	    u32 svm_urma_seg_flag = 0;
169	
170	    svm_urma_seg_flag |= ((ascend_flag & ASCEND_URMA_SEG_FLAG_ACCESS_WRITE) != 0) ? SVM_URMA_SEG_FLAG_ACCESS_WRITE : 0;
171	    svm_urma_seg_flag |= ((ascend_flag & ASCEND_URMA_SEG_FLAG_PIN) != 0) ? SVM_URMA_SEG_FLAG_PIN : 0;
172	    svm_urma_seg_flag |= ((ascend_flag & ASCEND_URMA_SEG_FLAG_WITHOUT_TOKEN_VAL) != 0) ? SVM_URMA_SEG_FLAG_SELF_USER :
173	                                                                                         0;
174	
175	    return svm_urma_seg_flag;
176	}
177	
178	static void ascend_to_svm_urma_seg_info(struct ascend_urma_seg_info *ascend_info, struct svm_urma_seg_info *svm_info)
179	{
180	    svm_info->start = ascend_info->start;
181	    svm_info->size = ascend_info->size;
182	    svm_info->token_id = ascend_info->token_id;
183	    svm_info->token_val = ascend_info->token_val;
184	    svm_info->seg_flag = ascend_to_svm_urma_seg_flag(ascend_info->seg_flag);
185	    svm_info->tseg = ascend_info->tseg;
186	}
187	
188	int svm_urma_seg_local_get_info(u32 devid, u64 va, u32 seg_flag, struct svm_urma_seg_info *seg_info)
189	{
190	    u32 user_devid = svm_urma_seg_get_user_devid(devid);
191	    struct ascend_urma_seg_info info;
192	    int ret;
193	
194	    if (devid >= SVM_MAX_DEV_AGENT_NUM) {
195	        svm_err("Invalid devid. (devid=%u)\n", devid);
196	        return DRV_ERROR_INVALID_VALUE;
197	    }
198	
199	    if (!svm_urma_seg_local_is_dev_inited(user_devid)) {
200	        svm_err("Uninit. (devid=%u)\n", user_devid);
201	        return DRV_ERROR_INVALID_VALUE;
202	    }
203	
204	    ret = ascend_urma_get_seg_info(svm_get_urma_seg_mng(user_devid, seg_flag), va, &info);
205	    if (ret == DRV_ERROR_NONE) {
206	        ascend_to_svm_urma_seg_info(&info, seg_info);
207	    }
208	
209	    return ret;
210	}
211	
212	int svm_urma_seg_local_dev_init(u32 devid)
213	{
214	    u32 user_devid = svm_urma_seg_get_user_devid(devid);
215	
216	    if ((devid == svm_get_host_devid()) || !ascend_urma_dev_is_exist(user_devid) ||
217	        svm_urma_seg_local_is_dev_inited(user_devid)) {
218	        return DRV_ERROR_NONE;
219	    }
220	
221	    return _svm_urma_seg_local_dev_init(user_devid);
222	}
223	
224	int svm_urma_seg_local_dev_uninit(u32 devid)
225	{
226	    u32 user_devid = svm_urma_seg_get_user_devid(devid);
227	
228	    if ((devid == svm_get_host_devid()) || !ascend_urma_dev_is_exist(user_devid) ||
229	        (svm_is_in_host_side() && (devid != svm_get_host_devid()))) {
230	        return DRV_ERROR_NONE;
231	    }
232	
233	    if (svm_urma_seg_local_is_dev_inited(user_devid)) {
234	        _svm_urma_seg_local_dev_uninit(user_devid);
235	    }
236	
237	    return DRV_ERROR_NONE;
238	}
239	
240	static int svm_urma_seg_local_criu_reset(u32 devid, void *data)
241	{
242	    SVM_UNUSED(data);
243	    svm_urma_seg_local_reset_state();
244	    if (devid < SVM_MAX_DEV_AGENT_NUM && svm_urma_seg_local_is_dev_inited(devid)) {
245	        _svm_urma_seg_local_dev_uninit(devid);
246	    }
247	    return DRV_ERROR_NONE;
248	}
249	
250	static const struct svm_criu_ops g_urma_seg_local_criu_ops = {
251	    .name = "urma_seg_local",
252	    .reset = svm_urma_seg_local_criu_reset,
253	};
254	
255	static void __attribute__((constructor(SVM_INIT_PRI_LOW))) svm_urma_seg_local_init(void)
256	{
257	    int ret;
258	
259	    ret = svm_register_ioctl_dev_init_post_handle(svm_urma_seg_local_dev_init);
260	    if (ret != DRV_ERROR_NONE) {
261	        svm_err("Register ioctl dev init post handle failed.\n");
262	    }
263	
264	    ret = svm_register_ioctl_dev_uninit_pre_handle(svm_urma_seg_local_dev_uninit);
265	    if (ret != DRV_ERROR_NONE) {
266	        svm_err("Register ioctl dev uninit pre handle failed.\n");
267	    }
268	
269	    ret = svm_criu_register_ops(&g_urma_seg_local_criu_ops);
270	    if (ret != DRV_ERROR_NONE) {
271	        svm_err("Register CRIU ops failed.\n");
272	    }
273	}
